        export namespace VecnyProfil {

            /**
             * Doplnění číselníkových a dalších hodnot do seznamu Věcného profilu
             * 
             * @param {Gordic.Ada.Interface.GVepsplaDto[] | null} data seznam Věcného profilu
             * @returns {JQueryPromise<Gordic.Ada.Interface.GVepsplaDto[]>} doplněný seznam Věcného profilu
             */
            export function modifyDto(data: Gordic.Ada.Interface.GVepsplaDto[] | null): JQueryPromise<Gordic.Ada.Interface.GVepsplaDto[]> {

                let defClose = $.Deferred();

                if (data !== null) {

                    // číselníky
                    let dataVepsdup: Data.Readers.VepsdupDto[];
                    let dataGincmej: Data.Readers.GincmejDto[];
                    let dataVepcstp: Gordic.Ada.Interface.GVepcstpDto[]; 
                    
                    let promises: JQueryPromise<any>[] = [];

                    promises.push(new Gordic.Data.Readers.Vepsdup().getData().then((dataReader) => { dataVepsdup = dataReader; }));
                    promises.push(new Gordic.Data.Readers.Gincmej().getData().then((dataReader) => { dataGincmej = dataReader; }));
                    promises.push(new Gordic.Data.Readers.Vepcstp().getData().then((dataReader) => { dataVepcstp = dataReader; }));

                    $.when.apply(null, promises).then(() => {
                        // doplnění textových hodnot k číselníkovým
                        for (let i = 0, l = data.length; i < l; i++) {
                            // typ polozky VP
                            let dup = dataVepsdup.find(function (element) { return (element.ixs_dup === data[i].ixs_dup); });
                            if (dup !== undefined) data[i].ixs_dup_nazev = dup.nazev || "";

                            // MJ
                            let mej = dataGincmej.find(function (element) { return (element.mj === data[i].mj); });
                            if (mej !== undefined) data[i].mj_nazev = mej.mj_zkr || "";

                            // MJ
                            let vp_stav = dataVepcstp.find(function (element) { return (element.vp_stav === data[i].vp_stav); });
                            if (vp_stav !== undefined) data[i].vp_stav_nazev = vp_stav.vp_stav_txt || "";

                        }
                        defClose.resolve(data);
                    });
                }
                else {
                    defClose.resolve(data);
                }

                return defClose.promise();
            }
        }
